// Parse df output → identify drives that can ACCEPT vs REFUSE library moves
// Per RSP decree 2026-04-20: RESPECT DEVICE VOLUME SIZE
const out = $input.first().json.stdout || '';
const lines = out.split('\n').filter(l => l.includes('|'));
const CAPACITY_HEADROOM_PCT = 80; // never exceed 80% on a target drive

const drives = lines.map(line => {
  const [path, available, usedPct] = line.split('|');
  const used = parseInt(usedPct);
  return {
    path: path.trim(),
    available: available.trim(),
    used_pct: isNaN(used) ? 100 : used,
    can_accept: !isNaN(used) && used < CAPACITY_HEADROOM_PCT,
    role: 'unknown'
  };
});

// Classify each drive's role + accept/refuse for commercial library overflow
const CANDIDATES = {
  '/Volumes/RSP_GOFISH': 'AVAILABLE_TARGET (1% used · primary overflow target)',
  '/Volumes/12TB':       'MASTER_ARCHIVE (87% — full · cannot accept)',
  '/Volumes/6TB':        'DOCTRINE_ARCHIVE (86% — full · cannot accept)',
  '/Volumes/4TB BLK':    'OVERFLOW_BLOCKER (100% — must EVACUATE from)',
  '/Volumes/4TB Blue Fish': 'OVERFLOW_PENDING (99% — cannot accept · should rotate)',
  '/Volumes/MAG 4TB':    'SAMPLE_OVERFLOW (80% — limited capacity)',
  '/Volumes/4TB Big Fish': 'PRIMARY_FISH (48% — can accept)',
  '/Volumes/4TB FISH SG': 'FISH_SAMPLES (82% — limited)',
  '/Volumes/4TB Lacie':  'EMPIRE_MIRROR (17% — can accept · note: also Design Reunion home)',
  '/Volumes/JOE':        'GORUNFREE_RECOVERY (56% — can accept moderate)'
};

return drives.map(d => ({
  json: {
    ...d,
    role: CANDIDATES[d.path] || d.role,
    timestamp: new Date().toISOString()
  }
}));

// For each found library, propose a move target based on capacity-classified drives
// + the library's vendor canonical home convention
const libraryPaths = ($input.first().json.stdout || '').split('\n').filter(Boolean);
const drives = $input.last().json || [];

// Canonical home per vendor (vendor → preferred volume root)
const CANONICAL_HOME = {
  'XLN_Audio':           '/Volumes/RSP_GOFISH/_LIBRARIES/XLN_Audio',
  'Avid':                '/Volumes/RSP_GOFISH/_LIBRARIES/Avid',
  'Native_Instruments':  '/Volumes/4TB Big Fish/_LIBRARIES/Native_Instruments',
  'Native Instruments':  '/Volumes/4TB Big Fish/_LIBRARIES/Native_Instruments',
  'IK Multimedia':       '/Volumes/4TB Big Fish/_LIBRARIES/IK_Multimedia',
  'Toontrack':           '/Volumes/4TB Big Fish/_LIBRARIES/Toontrack',
  'Sample Magic':        '/Volumes/MAG 4TB/_LIBRARIES/Sample_Magic',
  'Sample_Magic':        '/Volumes/MAG 4TB/_LIBRARIES/Sample_Magic',
  'Best_Service':        '/Volumes/MAG 4TB/_LIBRARIES/Best_Service',
  'Earth_Moments':       '/Volumes/MAG 4TB/_LIBRARIES/Earth_Moments',
  'Steven_Slate':        '/Volumes/MAG 4TB/_LIBRARIES/Steven_Slate'
};

return libraryPaths.map(currentPath => {
  const dirName = currentPath.split('/').pop();
  const target = CANONICAL_HOME[dirName] || `/Volumes/RSP_GOFISH/_UNCLASSIFIED/${dirName}`;
  const targetVolume = '/' + target.split('/').slice(1, 3).join('/');
  const targetDrive = drives.find(d => d.path === targetVolume);
  const can_move = targetDrive ? targetDrive.can_accept : false;

  return {
    json: {
      current_path: currentPath,
      vendor: dirName,
      proposed_target: target,
      target_volume: targetVolume,
      target_can_accept: can_move,
      action: can_move ? 'PROPOSE_MOVE' : 'BLOCKED — target full',
      command_dry_run: `# DRY RUN — review before executing\nrsync -av --dry-run "${currentPath}/" "${target}/"`,
      command_execute: `# DESTRUCTIVE — only after RSP review\nmkdir -p "${target}" && rsync -av --remove-source-files "${currentPath}/" "${target}/" && find "${currentPath}" -depth -type d -empty -delete`
    }
  };
});
